-- Load seed data for schema 'healthcare'.
-- Run from this folder after creating the schema:  psql -d yourdb -f load_healthcare.sql
\set ON_ERROR_STOP on
BEGIN;
SET search_path TO healthcare;

-- Identity columns are GENERATED ALWAYS; allow explicit ids while loading.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'healthcare' AND is_identity = 'YES' AND identity_generation = 'ALWAYS' LOOP
    EXECUTE format('ALTER TABLE healthcare.%I ALTER COLUMN %I SET GENERATED BY DEFAULT', r.table_name, r.column_name);
  END LOOP; END $$;

\copy facilities (facility_id, name, facility_type, npi, address_line1, city, state, postal_code, address_line2, country, phone, created_at, updated_at) FROM 'facilities.csv' WITH (FORMAT csv, HEADER true)
\copy departments (department_id, facility_id, name, code) FROM 'departments.csv' WITH (FORMAT csv, HEADER true)
\copy providers (provider_id, npi, first_name, last_name, credential, specialty, license_number, license_state, license_expires, email, phone, is_active, created_at, updated_at) FROM 'providers.csv' WITH (FORMAT csv, HEADER true)
\copy provider_departments (provider_id, department_id, is_primary) FROM 'provider_departments.csv' WITH (FORMAT csv, HEADER true)
\copy patients (patient_id, mrn, first_name, middle_name, last_name, date_of_birth, sex_at_birth, gender_identity, ssn_last4, email, phone, address_line1, city, state, postal_code, address_line2, country, preferred_language, blood_type, primary_provider_id, is_deceased, deceased_at, created_at, updated_at) FROM 'patients.csv' WITH (FORMAT csv, HEADER true)
\copy emergency_contacts (contact_id, patient_id, full_name, relationship, phone, is_primary) FROM 'emergency_contacts.csv' WITH (FORMAT csv, HEADER true)
\copy allergies (allergy_id, patient_id, allergen, reaction, severity, onset_date, recorded_by, recorded_at) FROM 'allergies.csv' WITH (FORMAT csv, HEADER true)
\copy insurance_payers (payer_id, name, payer_code, phone, claims_address) FROM 'insurance_payers.csv' WITH (FORMAT csv, HEADER true)
\copy patient_insurance (patient_insurance_id, patient_id, payer_id, member_id, group_number, plan_name, subscriber_name, relationship_to_subscriber, priority, effective_date, termination_date, copay_amount) FROM 'patient_insurance.csv' WITH (FORMAT csv, HEADER true)
\copy appointments (appointment_id, patient_id, provider_id, department_id, scheduled_start, scheduled_end, reason, status, cancel_reason, created_at, updated_at) FROM 'appointments.csv' WITH (FORMAT csv, HEADER true)
\copy encounters (encounter_id, patient_id, provider_id, facility_id, appointment_id, encounter_type, admitted_at, discharged_at, chief_complaint, clinical_notes, discharge_disposition, created_at) FROM 'encounters.csv' WITH (FORMAT csv, HEADER true)
\copy vitals (vital_id, encounter_id, recorded_at, temperature_c, heart_rate_bpm, systolic_bp, diastolic_bp, respiratory_rate, spo2_percent, height_cm, weight_kg, recorded_by) FROM 'vitals.csv' WITH (FORMAT csv, HEADER true)
\copy icd10_codes (code, description) FROM 'icd10_codes.csv' WITH (FORMAT csv, HEADER true)
\copy cpt_codes (code, description, standard_charge) FROM 'cpt_codes.csv' WITH (FORMAT csv, HEADER true)
\copy diagnoses (diagnosis_id, encounter_id, icd10_code, is_primary, notes, diagnosed_by) FROM 'diagnoses.csv' WITH (FORMAT csv, HEADER true)
\copy procedures (procedure_id, encounter_id, cpt_code, performed_by, performed_at, notes) FROM 'procedures.csv' WITH (FORMAT csv, HEADER true)
\copy medications (medication_id, ndc_code, generic_name, brand_name, strength, dosage_form, is_controlled, dea_schedule) FROM 'medications.csv' WITH (FORMAT csv, HEADER true)
\copy prescriptions (prescription_id, patient_id, encounter_id, prescriber_id, medication_id, dose, route, frequency, quantity, refills, start_date, end_date, status, instructions, created_at) FROM 'prescriptions.csv' WITH (FORMAT csv, HEADER true)
\copy lab_tests (lab_test_id, loinc_code, name, unit, reference_low, reference_high, specimen_type) FROM 'lab_tests.csv' WITH (FORMAT csv, HEADER true)
\copy lab_orders (lab_order_id, encounter_id, ordered_by, lab_test_id, priority, status, ordered_at, collected_at) FROM 'lab_orders.csv' WITH (FORMAT csv, HEADER true)
\copy lab_results (lab_result_id, lab_order_id, value_numeric, value_text, abnormal_flag, resulted_at, verified_by, comments) FROM 'lab_results.csv' WITH (FORMAT csv, HEADER true)
\copy claims (claim_id, claim_number, encounter_id, patient_insurance_id, status, total_billed, total_allowed, total_paid, patient_responsibility, denial_reason, submitted_at, adjudicated_at, created_at, updated_at) FROM 'claims.csv' WITH (FORMAT csv, HEADER true)
\copy claim_lines (claim_line_id, claim_id, line_number, cpt_code, icd10_code, units, charge_amount, paid_amount) FROM 'claim_lines.csv' WITH (FORMAT csv, HEADER true)
\copy patient_payments (payment_id, patient_id, claim_id, amount, method, reference, paid_at) FROM 'patient_payments.csv' WITH (FORMAT csv, HEADER true)
\copy audit_log (audit_id, user_id, patient_id, action, table_name, record_id, ip_address, occurred_at) FROM 'audit_log.csv' WITH (FORMAT csv, HEADER true)

-- Restore GENERATED ALWAYS and move sequences past the loaded ids.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'healthcare' AND is_identity = 'YES' LOOP
    EXECUTE format('SELECT setval(pg_get_serial_sequence(''healthcare.%I'', %L), COALESCE((SELECT max(%I) FROM healthcare.%I), 0) + 1, false)',
                   r.table_name, r.column_name, r.column_name, r.table_name);
    EXECUTE format('ALTER TABLE healthcare.%I ALTER COLUMN %I SET GENERATED ALWAYS', r.table_name, r.column_name);
  END LOOP; END $$;

COMMIT;
